import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { installModels, readAssetPackage } from "../upload_models.mjs";

// Use binary data across several transfer boundaries, including a short final chunk.
function modelFixture() {
	const image = Buffer.from(Array.from({ length: 1553 }, (_, i) => i % 256));
	const sha256 = createHash("sha256").update(image).digest("hex");
	return {
		file: "model-test.webp",
		path: "/inter_comms/model-" + sha256.slice(0, 16) + ".webp",
		sha256,
		size: image.length,
		image,
	};
}

test("model installer transfers exact binary content and finishes only after every byte", async () => {
	const model = modelFixture();
	const received = [];
	let finished = false;
	await installModels("http://device", [model], {
		send: async (address, command) => {
			assert.equal(address, "http://device");
			if (command.op === "modelStatus") return { models: [{ ...model, installed: false }] };
			assert.equal(command.body.path, model.path);
			if (command.op === "modelChunk") {
				assert.equal(command.body.offset, Buffer.concat(received).length);
				const bytes = Buffer.from(command.body.data, "hex");
				assert.ok(bytes.length <= 768);
				received.push(bytes);
			} else if (command.op === "modelFinish") {
				assert.deepEqual(Buffer.concat(received), model.image);
				finished = true;
			} else assert.equal(command.op, "modelBegin");
			return { ok: true };
		},
	});
	assert.ok(finished);
});

test("model installer leaves already installed files alone", async () => {
	const model = modelFixture();
	const calls = [];
	await installModels("http://device", [model], {
		send: async (_, command) => {
			calls.push(command.op);
			return { models: [{ ...model, installed: true }] };
		},
	});
	assert.deepEqual(calls, ["modelStatus"]);
});

test("a mismatched firmware manifest prevents every model write", async () => {
	const models = [modelFixture(), { ...modelFixture(), path: "/inter_comms/model-0000000000000000.webp" }];
	const calls = [];
	await assert.rejects(
		installModels("http://device", models, {
			send: async (_, command) => {
				calls.push(command.op);
				return { models: [{ ...models[0], installed: false }] };
			},
		}),
		/matching firmware/,
	);
	assert.deepEqual(calls, ["modelStatus"]);
});

test("an interrupted upload is aborted without publishing a partial file", async () => {
	const model = modelFixture();
	const calls = [];
	await assert.rejects(
		installModels("http://device", [model], {
			send: async (_, command) => {
				calls.push(command.op);
				if (command.op === "modelStatus") return { models: [{ ...model, installed: false }] };
				if (command.op === "modelChunk" && command.body.offset > 0) throw new Error("Connection lost");
				return { ok: true };
			},
		}),
		/Connection lost/,
	);
	assert.deepEqual(calls, ["modelStatus", "modelBegin", "modelChunk", "modelChunk", "modelAbort"]);
});

test("package loading rejects damaged content and paths outside the model directory", async (t) => {
	const directory = await mkdtemp(join(tmpdir(), "inter-comms-model-assets-"));
	t.after(() => rm(directory, { recursive: true, force: true }));
	const model = modelFixture();
	const { image, ...entry } = model;
	await mkdir(join(directory, "inter_comms"));
	const manifest = join(directory, "manifest.json");
	await writeFile(manifest, JSON.stringify([entry]));
	const file = join(directory, model.path.slice(1));
	await writeFile(file, image);
	const url = pathToFileURL(directory + "/");
	assert.deepEqual((await readAssetPackage(url))[0].image, image);
	await writeFile(file, Buffer.alloc(image.length));
	await assert.rejects(readAssetPackage(url), /damaged/);
	await writeFile(manifest, JSON.stringify([{ ...entry, path: "/cfg.json" }]));
	await assert.rejects(readAssetPackage(url), /Invalid model manifest entry/);
});
